old = {"S01_끼어들기": "PASS", "S02_정차차량": "PASS", "S03_비보호좌회전": "FAIL", "S04_보행자": "PASS"}
new = {"S01_끼어들기": "PASS", "S02_정차차량": "FAIL", "S03_비보호좌회전": "PASS", "S04_보행자": "PASS"}
for s in old:
    if old[s] != new[s]:
        kind = "고쳐짐" if new[s] == "PASS" else "퇴행"
        print(f"{s}: {old[s]} -> {new[s]}  {kind}")
print("통과", sum(v == "PASS" for v in old.values()), "->", sum(v == "PASS" for v in new.values()), "/", len(new))
# S02_정차차량: PASS -> FAIL  퇴행
# S03_비보호좌회전: FAIL -> PASS  고쳐짐
# 통과 3 -> 3 / 4
